/* Elevate course catalogue, parts B and C */
const COURSES_B = [
{
  id:"c-logi-1", dom:"logi", title:"Logistics, Incoterms & Canadian Trade Compliance",
  level:[1,4], cpd:11,
  blurb:"Modal decisions, Incoterms 2020, CUSMA rules of origin and CBSA obligations, written for Western Canadian cross-border operations.",
  modules:[
  { title:"Moving Freight",
    lessons:[
    { id:"l1", title:"Choosing a mode: the real trade-offs", mins:7,
      body:"<p>Mode selection is usually presented as a cost-versus-speed trade-off, which understates it. Four variables move together.</p><p><strong>Cost per unit</strong> falls as you move from air to truck to rail to ocean. <strong>Transit time</strong> rises in the same direction. <strong>Variability</strong> matters more than average transit: rail is cheap but its arrival window is wider, and a wider window means more safety stock. <strong>Shipment size economics</strong> determine whether you are paying LTL rates on volume that should be consolidated into truckload.</p><p>The connected decision is inventory. A cheaper, slower, more variable mode requires more stock in the pipeline and more buffer at the destination. Comparing freight rates without pricing that inventory produces a decision that looks good in the transportation budget and costs more overall.</p><p>In Western Canada, add corridor reliability. Mountain pass closures are a seasonal certainty rather than an exception, and a plan built on average transit will fail in the months it matters most.</p>",
      keyPoints:["Variability matters more than average transit time","Mode choice changes required inventory","Build mountain corridor closures into the plan, not the exceptions"],
      check:{q:"Switching from truck to rail saves 18% on freight but widens the arrival window from 2 days to 6. The hidden cost is:",opts:["Higher handling charges","Additional safety stock required to cover the wider arrival window, which may exceed the freight saving","Loss of carrier relationship","Increased customs complexity"],a:1,why:"Wider arrival variability is absorbed by inventory. That cost sits in a different budget and is routinely omitted from the comparison."} },

    { id:"l2", title:"Incoterms 2020 without the confusion", mins:9,
      body:"<p>Incoterms allocate three things between buyer and seller: who pays for what portion of transport, where risk of loss transfers, and who handles export and import formalities. They do not address title, payment or breach.</p><p>The terms divide usefully into groups. <strong>EXW</strong> places almost everything on the buyer. <strong>FCA, FAS, FOB</strong> transfer risk at origin, with the buyer arranging main carriage. <strong>CFR, CIF, CPT, CIP</strong> have the seller pay main carriage but risk still transfers at origin, which is the most commonly misunderstood point in the whole framework. <strong>DAP, DPU, DDP</strong> are delivered terms where the seller carries risk to destination.</p><p>Two practical errors dominate. Using FOB for containerized freight, where FCA is the correct term because risk should transfer at the container yard rather than at the ship's rail. And agreeing DDP without the seller understanding they must act as importer of record in Canada, which has GST and compliance consequences they may not be equipped to handle.</p>",
      keyPoints:["C-terms: seller pays carriage but risk transfers at origin","Use FCA rather than FOB for containerized freight","DDP makes the seller importer of record in Canada"],
      check:{q:"Under CIF, goods are damaged during ocean transit. Who bears the loss?",opts:["The seller, since they arranged and paid for carriage","The buyer, since risk transferred at origin even though the seller paid the freight and insurance","Shared equally","The carrier automatically"],a:1,why:"The separation of cost from risk is the defining feature of the C-terms and the most frequent source of disputes."} },

    { id:"l3", title:"Freight cost control and accessorial charges", mins:8,
      body:"<p>Base rates get negotiated. Accessorials are where the money quietly leaves, and in many operations they add 15% to 30% on top of the linehaul.</p><p>The frequent ones are fuel surcharge, residential and limited-access delivery, liftgate, detention, reweigh and reclassification, redelivery, and storage. Most are self-inflicted or preventable at origin.</p><p><strong>Reweigh and reclass</strong> charges mean the dimensions, weight or freight class on your bill of lading were wrong. The fix is accurate dimensioning at shipping rather than disputing each charge afterwards, which is expensive and rarely successful.</p><p><strong>Detention</strong> means your facility held the equipment past free time. That is a dock scheduling problem wearing a transportation cost label.</p><p>Build a freight audit process that compares invoice against contracted rate and flags accessorial patterns. The value of the audit is not the individual recoveries; it is discovering that one site generates most of the detention charges and fixing that site.</p>",
      keyPoints:["Accessorials often add 15-30% over linehaul","Reweigh and reclass charges are origin data problems","Freight audit's real value is finding patterns, not recovering individual charges"],
      check:{q:"One DC generates 70% of your detention charges. The correct response is:",opts:["Negotiate longer free time with the carrier","Examine dock scheduling, appointment adherence and unloading resources at that site, since the charge reflects an internal constraint","Change carriers","Accept it as a cost of doing business"],a:1,why:"Detention is incurred by your own operation. Buying more free time treats the symptom and leaves the constraint in place."} }
  ]},
  { title:"Cross-Border Compliance",
    lessons:[
    { id:"l4", title:"CBSA obligations and the importer of record", mins:8,
      body:"<p>The importer of record carries legal responsibility for the accuracy of a customs declaration, for paying duties and taxes, and for keeping records. That responsibility does not transfer to the customs broker, who acts as your agent. Organizations regularly assume otherwise and discover the distinction during a verification.</p><p>Three obligations matter most. <strong>Accurate tariff classification</strong>, because the HS code determines duty rate and admissibility, and classification errors compound silently across thousands of transactions. <strong>Accurate valuation</strong>, using the correct valuation method and including dutiable additions such as assists and certain royalties. <strong>Record retention</strong>, generally six years plus the current year, in a form CBSA can examine.</p><p>CBSA conducts verification priorities by commodity, published periodically. If your category appears on that list, a review of your classification history before the letter arrives is a great deal cheaper than after.</p><p>Voluntary disclosure, made before CBSA contacts you, is treated materially better than an error found during verification.</p>",
      keyPoints:["Responsibility stays with the importer of record, not the broker","Classification and valuation errors compound across transactions","Voluntary disclosure is treated far better than discovery"],
      check:{q:"Your broker has misclassified an item for three years. Responsibility for the resulting duty owing rests with:",opts:["The broker, as the classification expert","The importer of record, since the broker acts as agent and the legal obligation for accuracy is yours","CBSA, for not identifying it","The foreign supplier"],a:1,why:"Using an agent does not transfer the statutory obligation. This is why importers should review classification rather than delegate and forget it."} },

    { id:"l5", title:"CUSMA rules of origin and certification", mins:8,
      body:"<p>Preferential duty treatment under CUSMA is not granted because goods ship from the United States or Mexico. It is granted because the goods satisfy the agreement's rules of origin, which is a materially different test.</p><p>Two main approaches apply depending on the product. <strong>Tariff shift</strong> requires non-originating inputs to undergo a specified change in classification through production in the region. <strong>Regional value content</strong> requires a defined percentage of value to originate in the region, calculated by a prescribed method.</p><p>The claim is supported by a certification of origin, which under CUSMA has no prescribed form but must contain specified data elements and may be completed by the exporter, producer or importer. If the importer certifies, the importer must hold the information supporting it.</p><p>The practical exposure is that an unsupported claim discovered during verification results in duty, interest and potentially penalties, retroactive across the claim period. Obtain and retain supporting documentation at the time of the claim, not when the verification letter arrives.</p>",
      keyPoints:["Shipping from the US or Mexico does not establish origin","Tariff shift or regional value content is the actual test","Hold supporting documentation at the time of the claim"],
      check:{q:"Components made in Asia are assembled in Ohio and shipped to Calgary. CUSMA preference depends on:",opts:["The shipment originating in the United States","Whether the assembly produces the required tariff shift or regional value content under the applicable rule for that product","The value of the assembly labour alone","Whether the supplier is US-owned"],a:1,why:"Assembly may or may not confer origin depending on the specific product rule. This is exactly where unsupported claims arise."} },

    { id:"l6", title:"Managing a customs broker relationship", mins:6,
      body:"<p>A broker is a supplier like any other, and most organizations manage the relationship less actively than the spend and the risk justify.</p><p>Four things are worth active management. <strong>Classification governance</strong>: agree who assigns HS codes, how new items are handled, and how classification decisions are documented and reviewed. <strong>Data quality</strong>: brokers declare what you give them, so errors in your commercial invoices become your customs errors. <strong>Performance visibility</strong>: release times, examination rates and error rates should be reported, not assumed. <strong>Cost transparency</strong>: separate brokerage fees from disbursements so you can see what you are actually paying for the service.</p><p>Set a periodic classification review across your highest-volume items. The cost of that review is small against the retroactive exposure that a systematic classification error creates over several years of shipments.</p>",
      keyPoints:["Agree classification governance explicitly","Your invoice data quality becomes your customs accuracy","Separate brokerage fees from disbursements"],
      check:{q:"The most valuable periodic control over a brokerage relationship is:",opts:["Competitive tendering of brokerage fees","A classification review of high-volume items, since systematic errors accumulate retroactive exposure across years","Reviewing monthly invoices","Requiring 24-hour release times"],a:1,why:"Brokerage fees are small relative to the duty and penalty exposure created by a classification error repeated across thousands of entries."} }
  ]}]
},

{
  id:"c-inv-1", dom:"inv", title:"Inventory & Demand Planning",
  level:[1,4], cpd:10,
  blurb:"Forecasting, buffer sizing, replenishment policy and S&OP, with the arithmetic explained rather than assumed.",
  modules:[
  { title:"Demand",
    lessons:[
    { id:"l1", title:"What a forecast is for", mins:6,
      body:"<p>A forecast is not a prediction that will turn out to be right. It is an input to decisions that must be made before demand is known, and its purpose is to make those decisions better than they would be without it.</p><p>That framing matters because it changes what you optimize. If a forecast exists to be accurate, you spend your effort on the model. If it exists to support decisions, you spend it on the decisions that are actually sensitive to it, and on reducing the lead time that forces you to decide so far ahead.</p><p>Two diagnostics describe a forecast. <strong>Bias</strong> is systematic tilt: consistently over or under. Bias is correctable and always worth fixing, because it accumulates into excess stock or chronic shortage. <strong>Accuracy</strong>, commonly measured as MAPE, is the size of typical error regardless of direction. Random error is managed with buffers and shorter lead times rather than with better models.</p><p>Knowing which problem you have determines whether to fix the forecast or the response to it.</p>",
      keyPoints:["Forecasts support decisions; they are not predictions to be graded","Bias is correctable and always worth fixing","Random error is managed with buffers and shorter lead times"],
      check:{q:"Your forecast runs 12% above actual demand in 10 of 12 months. This is:",opts:["Random error requiring larger buffers","Systematic bias, which should be diagnosed and corrected rather than absorbed by inventory","Acceptable forecast performance","A demand problem rather than a forecast problem"],a:1,why:"Consistent one-directional error is bias. Absorbing it with inventory funds a correctable problem indefinitely."} },

    { id:"l2", title:"Segmenting demand before forecasting it", mins:7,
      body:"<p>Applying one forecasting approach across every item guarantees poor results, because items differ in ways that determine what method can work.</p><p>Segment on two dimensions. <strong>Volume</strong>, which tells you how much attention the item justifies. <strong>Variability</strong>, which tells you whether statistical forecasting is viable at all.</p><p>High volume and stable demand is where statistical methods work well and should be automated. High volume with erratic demand needs collaboration with sales or customers rather than a better algorithm. Low volume and stable demand can run on simple reorder rules. Low volume and erratic demand, which describes most spare parts, should not be forecast in the usual sense at all; it should be managed by service level and buffer policy.</p><p>The common failure is spending planner attention on the low-volume erratic items because they cause the visible stockouts, while the high-volume items that carry the money drift on default settings.</p>",
      keyPoints:["Segment by volume and variability before choosing a method","Erratic low-volume items should not be statistically forecast","Planner attention should follow value, not noise"],
      check:{q:"A spare part sells 0 to 3 units in most months with occasional spikes of 20. The right approach is:",opts:["A more sophisticated forecasting model","Manage it by target service level and buffer policy rather than by forecast, since intermittent demand is not reliably forecastable","Remove it from stock","Forecast using a 12-month moving average"],a:1,why:"Intermittent demand resists forecasting. The decision that matters is how much protection the item warrants, not what next month's number is."} },

    { id:"l3", title:"S&OP: the decision forum", mins:8,
      body:"<p>Sales and operations planning is frequently described as a forecasting process, which is why so many implementations produce meetings without decisions.</p><p>S&OP exists to reconcile four plans that are otherwise made independently and inconsistently: the demand plan from commercial, the supply plan from operations, the inventory plan, and the financial plan. Its output is one agreed operating plan and, critically, a set of decisions about the gaps.</p><p>The monthly cycle runs demand review, supply review, reconciliation where gaps and options are prepared, and an executive meeting where trade-offs are decided. The executive meeting is the point of the whole exercise. If it becomes a status update, the process has failed regardless of how good the preceding analysis was.</p><p>The signal that S&OP is working is that difficult trade-offs are made in the room, with named owners, rather than being resolved later by whoever shouts loudest during the shortage.</p>",
      keyPoints:["S&OP reconciles demand, supply, inventory and financial plans","The executive meeting exists to decide, not to be updated","Success looks like trade-offs decided in advance"],
      check:{q:"Your S&OP executive meeting reviews performance but makes no decisions. The likely cause is:",opts:["Insufficient data","Gaps and options are not being prepared in the reconciliation step, so there is nothing framed for a decision","Wrong attendees","Meeting is too short"],a:1,why:"Executives decide between prepared options. Without a reconciliation step that frames the trade-offs, there is nothing to decide on."} }
  ]},
  { title:"Supply and Buffers",
    lessons:[
    { id:"l4", title:"Sizing safety stock properly", mins:9,
      body:"<p>Safety stock covers uncertainty during the replenishment lead time. Cycle stock covers expected demand between orders. Confusing the two produces buffers that are simultaneously too large in aggregate and too small where it matters.</p><p>The standard formula multiplies a service factor by the standard deviation of demand over lead time. Three consequences follow that are worth holding onto even without the arithmetic.</p><p><strong>Safety stock scales with the square root of lead time.</strong> Doubling lead time increases the requirement by about 41%, not 100%. This is also why lead time reduction is such a strong lever: halving it cuts the buffer by roughly 29%.</p><p><strong>It scales with demand variability, not demand volume.</strong> A high-volume stable item may need less buffer than a low-volume erratic one.</p><p><strong>It rises steeply at high service levels.</strong> Moving from 95% to 99% can nearly double the buffer, which is why blanket high service targets across all items are expensive and rarely justified.</p>",
      keyPoints:["Safety stock scales with the square root of lead time","It follows variability, not volume","The cost of service rises steeply above 95%"],
      check:{q:"Reducing supplier lead time from 8 weeks to 4 weeks reduces required safety stock by roughly:",opts:["50%","29%","75%","No change"],a:1,why:"The square root relationship means halving lead time cuts the buffer by about 1 minus the square root of 0.5, roughly 29%."} },

    { id:"l5", title:"Replenishment policies and when to use them", mins:7,
      body:"<p>Three policies cover most situations, and the choice should follow item characteristics rather than system defaults.</p><p><strong>Reorder point</strong> triggers an order of fixed quantity when stock falls to a calculated level. It suits steady demand with reliable lead times and works well when stock is monitored continuously.</p><p><strong>Periodic review</strong> checks stock at fixed intervals and orders up to a target. It suits items ordered together from one supplier, since it allows consolidation, but requires more buffer because it must cover the review period as well as the lead time.</p><p><strong>Min-max</strong> is a practical hybrid widely used in maintenance and MRO environments.</p><p>The errors that cause the most damage are static parameters. Reorder points calculated once and never revisited become wrong as demand and lead times drift, and the resulting stockouts get blamed on suppliers. A scheduled parameter review, at least annually and more often for A items, is what keeps the policy connected to reality.</p>",
      keyPoints:["Policy choice follows demand pattern and review capability","Periodic review needs more buffer but enables consolidation","Static parameters silently become wrong"],
      check:{q:"Stockouts have risen across many items with no change in supplier performance. The first thing to check is:",opts:["Supplier capacity","Whether reorder points and safety stock parameters have been recalculated as demand patterns and lead times changed","Warehouse accuracy","Forecast model selection"],a:1,why:"Stale parameters are the most common cause of widespread stockouts that cannot be traced to a supplier or a specific item."} },

    { id:"l6", title:"Excess, obsolescence and the honest write-down", mins:7,
      body:"<p>Excess inventory is a decision that has already been made and not yet recognized. The stock exists, the cash is spent, and the only remaining question is how much of it can be recovered.</p><p>Organizations delay that recognition because a write-down is visible and the carrying cost is not. Meanwhile obsolete stock consumes space, gets counted, gets moved, and occasionally gets used in place of the correct part.</p><p>A workable discipline has three parts. <strong>Classify regularly</strong> using consumption history and known demand, not intuition. <strong>Act in a defined sequence</strong>: redeploy to another site, return to supplier where an agreement permits, sell into a secondary market, then dispose. <strong>Trace root causes</strong>, because excess is a symptom. Common origins are minimum order quantities disconnected from demand, engineering changes without a run-down plan, forecast bias, and cancelled projects whose materials were never reviewed.</p><p>Fixing the origin prevents the next accumulation; the write-down only cleans up the last one.</p>",
      keyPoints:["Excess is an unrecognized past decision","Follow a defined disposition sequence before disposal","Trace root causes or the accumulation repeats"],
      check:{q:"An engineering change makes 400 units obsolete. The preventable root cause is:",opts:["Poor forecasting","No run-down plan linking the engineering change to existing inventory and open orders","Supplier minimum order quantity","Excessive safety stock"],a:1,why:"Engineering changes are known in advance. Excess from them reflects a missing process link, not a forecasting failure."} }
  ]}]
},

{
  id:"c-ops-1", dom:"ops", title:"Warehouse Operations & Lean Improvement",
  level:[1,3], cpd:8,
  blurb:"Flow, layout, picking productivity and continuous improvement in distribution and MRO environments.",
  modules:[
  { title:"Flow and Layout",
    lessons:[
    { id:"l1", title:"Designing for flow", mins:7,
      body:"<p>A warehouse is a flow system, and most performance problems are flow problems presented as resource problems.</p><p>Freight enters, is received and verified, is put away, waits, is picked, is packed, and ships. Each transition is an opportunity for queueing, and queueing is where elapsed time accumulates. A facility where receiving and shipping compete for the same doors, or where putaway travels the full length of the building, has designed the waste in.</p><p>Three principles cover most of it. <strong>Minimize travel</strong>, since travel is the largest component of picking labour and it produces nothing. <strong>Separate flows that interfere</strong>, particularly inbound and outbound at the dock. <strong>Locate by velocity</strong>, so fast-moving items sit in the most accessible positions.</p><p>When assessing a facility, walk the product path rather than reading the layout drawing. The drawing shows the intended flow; the path shows what actually happens, including the staging area that appeared because putaway cannot keep up.</p>",
      keyPoints:["Most performance problems are flow problems","Travel is the largest component of picking labour","Walk the product path rather than reading the drawing"],
      check:{q:"Staging areas keep appearing in aisles. This most likely indicates:",opts:["Insufficient racking","A flow constraint: work arriving faster than the next step can absorb it, so inventory accumulates where the bottleneck sits","Poor housekeeping","Excess inventory"],a:1,why:"Unplanned accumulation marks a bottleneck. Adding storage hides it; finding the constrained step fixes it."} },

    { id:"l2", title:"Slotting and picking productivity", mins:8,
      body:"<p>Slotting decides where each item lives, and it is the highest-return improvement available in most distribution operations because it costs labour rather than capital.</p><p>The core principle is velocity-based placement: the most frequently picked items go in the most accessible locations, in the golden zone between roughly knee and shoulder height, closest to the pick path start. A minority of SKUs typically drives the large majority of picks, so getting those right captures most of the benefit.</p><p>Two refinements add further gain. <strong>Affinity slotting</strong> places items frequently ordered together near each other. <strong>Ergonomic slotting</strong> places heavy items at waist height, which reduces injury risk and the cost that follows it.</p><p>Beyond placement, reduce trips. <strong>Batch picking</strong> collects several orders in one pass. <strong>Zone picking</strong> keeps pickers in a defined area. Both cut travel per line, which is the metric that actually moves.</p><p>Slotting decays as demand shifts, so it needs periodic review rather than a one-time project.</p>",
      keyPoints:["Velocity-based placement captures most of the gain","Batch and zone picking cut travel per line","Slotting decays and needs periodic review"],
      check:{q:"After re-slotting, pick rates improve 22% then decay over eight months. The cause is:",opts:["Picker fatigue","Demand patterns shifted while slot assignments stayed fixed, so velocity placement drifted out of alignment","Equipment wear","Seasonal variation"],a:1,why:"Slotting is only correct relative to current demand. Without periodic review it degrades predictably."} },

    { id:"l3", title:"Cycle counting and inventory accuracy", mins:7,
      body:"<p>Annual wall-to-wall counts shut the operation down, produce a number that is stale within weeks, and reveal nothing about why the discrepancies occurred. Cycle counting counts a subset continuously, usually weighted so that high-value or high-movement items are counted more often.</p><p>The purpose is not the count. It is the investigation. A discrepancy is evidence of a process failure: a receiving error, an unrecorded movement, a picking substitution, damage not written off, or a unit of measure inconsistency. Counting and adjusting without finding the cause means you will count and adjust the same item again next quarter.</p><p>Measure accuracy at location level rather than in aggregate. Ninety-eight percent accuracy sounds healthy, but if the errors cluster in your fastest-moving items the operational impact is severe and the aggregate number conceals it.</p><p>Track adjustment reasons over time. The pattern tells you which process to fix.</p>",
      keyPoints:["The investigation matters more than the count","Measure at location level, not aggregate","Track adjustment reasons to find the failing process"],
      check:{q:"Cycle counts show accuracy at 97% but stockouts of available stock keep occurring. Likely explanation:",opts:["The counts are wrong","Errors are concentrated in high-velocity items, so the aggregate figure masks a severe operational problem","97% is acceptable","Demand exceeds forecast"],a:1,why:"Aggregate accuracy weights all items equally. Operational impact depends entirely on which items are wrong."} }
  ]},
  { title:"Improvement",
    lessons:[
    { id:"l4", title:"Value stream mapping in a supply chain context", mins:8,
      body:"<p>A value stream map traces a product or an order through every step, recording the time each step takes and the time it spends waiting between steps. Its power is in the comparison between those two figures.</p><p>A typical first map shows total elapsed time of weeks against value-added time of hours. That ratio is not a sign of incompetence; it is normal, and it points the improvement effort in the right direction. Making individual tasks faster changes the hours. Removing queues, batching and handoffs changes the weeks.</p><p>Map the current state by walking it, with a stopwatch and the people who do the work. Data pulled from the system describes what should happen. The walk shows the rework loop, the approval that waits two days for one signature, and the batch that forms because the next step runs twice a week.</p><p>Then map a realistic future state and identify the specific changes that get you there. A future state nobody believes is achievable produces no action.</p>",
      keyPoints:["The gap between elapsed and value-added time locates the opportunity","Walk the process rather than extracting it from the system","A future state must be believable to drive action"],
      check:{q:"A purchase requisition takes 11 days to become a PO; hands-on work is 40 minutes. The improvement focus should be:",opts:["Training buyers to work faster","Approval queues, handoffs and batching, since almost all elapsed time is waiting rather than working","Buying a new system","Increasing headcount"],a:1,why:"Task speed governs 40 minutes. Queue and approval design governs the other 10-plus days."} },

    { id:"l5", title:"Root cause analysis that actually finds causes", mins:7,
      body:"<p>Most root cause analysis stops at the first plausible explanation, which is usually a person or a supplier. That produces corrective actions like additional training and reminder emails, which is why the same problem returns.</p><p>Two disciplines help. <strong>Five whys</strong>, applied honestly, moves from the event toward the system: the part was wrong, because the wrong bin was picked, because two similar parts sit adjacent with similar numbers, because the item numbering scheme does not distinguish them visually. That last answer is fixable; the first three are not.</p><p><strong>Fishbone analysis</strong> forces consideration of categories people skip, typically method, machine, material, measurement and environment alongside the obvious one.</p><p>The test for a genuine root cause is simple: if you address it, can the problem recur through the same path? If the answer is yes, keep going. If a corrective action is a reminder to be careful, the analysis has not finished.</p>",
      keyPoints:["Stopping at the first explanation blames people for system design","Test: can the problem still recur through the same path?","A reminder to be careful is not a corrective action"],
      check:{q:"A picking error is traced to 'operator did not check the label'. The analysis is incomplete because:",opts:["Operators should be retrained","It has not asked why the process permits an unchecked pick to proceed undetected, which is the fixable system condition","The wrong operator was interviewed","Labels should be larger"],a:1,why:"Human error is a starting point. The system question is why the error was possible and why it was not caught."} }
  ]}]
},

{
  id:"c-fin-1", dom:"fin", title:"Supply Chain Finance & Analytics",
  level:[1,4], cpd:10,
  blurb:"TCO, working capital, business cases and the analytical work that makes supply chain credible to finance.",
  modules:[
  { title:"Cost and Cash",
    lessons:[
    { id:"l1", title:"Total cost of ownership in practice", mins:8,
      body:"<p>TCO counts everything the decision costs over the life of the asset or service, not just the invoice. The categories are acquisition, operating, maintenance, quality and failure, inventory and financing, and end of life.</p><p>The discipline that makes TCO useful rather than academic is bounding it. A model that tries to capture everything becomes unbuildable and unpersuasive. Include the costs that are material and that differ between the options, and say explicitly what you excluded and why.</p><p>Two elements are omitted most often and matter most. <strong>Inventory and pipeline cost</strong>, where a cheaper supplier with a longer lead time forces more stock. <strong>Failure cost</strong>, where lower reliability means downtime priced at what the operation actually loses.</p><p>Run a sensitivity check on the two or three assumptions that drive the result. If the conclusion flips on a plausible change in one variable, that is important information, and presenting it builds far more credibility than a single confident number.</p>",
      keyPoints:["Include costs that are material and that differ between options","Inventory cost and failure cost are the usual omissions","Sensitivity-test the assumptions that drive the answer"],
      check:{q:"Supplier A is 8% cheaper but has a 10-week lead time versus 3 weeks. The most likely TCO reversal comes from:",opts:["Freight charges","Additional pipeline and safety stock plus reduced responsiveness to demand change","Currency movement","Quality differences"],a:1,why:"A seven-week lead time gap materially increases required inventory, which is a real cost normally omitted from a price comparison."} },

    { id:"l2", title:"Working capital and the cash conversion cycle", mins:7,
      body:"<p>Supply chain decisions move cash, and cash is often the constraint executives actually care about. The cash conversion cycle expresses it as days inventory outstanding plus days sales outstanding minus days payable outstanding.</p><p>Supply chain owns the first and third terms directly. Reducing inventory days releases cash. Extending payment terms releases cash. Both have limits worth respecting.</p><p>Inventory reduction releases cash once, and if it is achieved by cutting buffers without reducing lead time or variability, it is paid for with service failures that cost more than the cash released.</p><p>Extending payment terms shifts financing to the supplier. A large supplier may absorb it. A small one borrows at a higher rate than you do and prices it back, or becomes financially fragile, which creates a supply risk you then own. Supply chain finance programs exist precisely to break this trade-off, letting you extend terms while the supplier is paid early at a rate based on your credit.</p>",
      keyPoints:["Supply chain owns inventory days and payable days","Cutting buffers without reducing variability buys cash with service","Term extension shifts financing cost to suppliers who may price it back"],
      check:{q:"Extending terms from 30 to 75 days with small local suppliers most likely produces:",opts:["A pure working capital gain","A working capital gain partly offset by price increases or heightened supplier financial risk, since small suppliers finance at higher rates","No supplier impact","Improved supplier relationships"],a:1,why:"Financing cost does not disappear; it moves to the party least able to carry it cheaply and returns as price or risk."} },

    { id:"l3", title:"Building a business case finance will approve", mins:8,
      body:"<p>Business cases fail on credibility far more often than on merit. Finance discounts benefits they cannot verify, and once discounted, the case usually stops clearing the hurdle.</p><p>Four things make a case credible. A <strong>baseline finance recognizes</strong>, built from their figures rather than yours and agreed before the case is written. <strong>Benefits traceable to line items</strong> they can check afterwards, with the tracking method agreed in advance. <strong>Honest costs</strong>, including internal time, change management and ongoing support, because a case that omits them is discovered during implementation and damages the next one. And <strong>stated assumptions with sensitivities</strong>, showing what happens if adoption is slower or benefits smaller.</p><p>Distinguish clearly between cash benefits, cost avoidance and non-financial benefits such as risk reduction or compliance. Blending them into one number is the fastest way to have the whole case discounted.</p>",
      keyPoints:["Agree the baseline with finance before writing the case","Make every benefit traceable and agree how it will be tracked","Never blend cash, avoidance and risk into one figure"],
      check:{q:"A case claims $400,000 savings without an agreed baseline. The likely outcome is:",opts:["Approval based on the size of the benefit","Discounting of the whole case, since an unverifiable benefit reduces confidence in every other figure in it","Request for more detail on costs","Automatic rejection"],a:1,why:"Credibility is assessed across the document. One unverifiable claim casts doubt on the rest."} }
  ]},
  { title:"Analytics",
    lessons:[
    { id:"l4", title:"Spend analytics: building a usable cube", mins:8,
      body:"<p>A spend cube organizes transactional spend along the dimensions you need to ask questions: supplier, category, business unit, time, and contract status.</p><p>The hard part is not the tool. It is the data. Four cleansing steps do most of the work. <strong>Supplier normalization</strong>, consolidating name variants and parent-subsidiary relationships. <strong>Categorization</strong>, mapping transactions to a taxonomy reflecting how the market sells rather than how the GL codes. <strong>Currency and timing normalization</strong>. And <strong>exclusion handling</strong>, deciding consistently how to treat intercompany, payroll and taxes.</p><p>Once built, the cube answers the questions that drive strategy: where is spend concentrated, where is it fragmented, what share flows through contracts, where does price vary for the same item, and which suppliers appear across multiple categories.</p><p>Before presenting any variance finding, verify comparability. Price variance findings collapse under scrutiny more often than any other analysis, usually because the item master is inconsistent.</p>",
      keyPoints:["The difficulty is data cleansing, not tooling","Categorize by how the market sells, not by GL code","Verify comparability before presenting price variance"],
      check:{q:"Your analysis shows the same part bought at $42 and $71 across sites. Before presenting, verify:",opts:["Which site is responsible","Whether the part numbers refer to genuinely identical items and whether volume, urgency or freight terms differ","The dashboard refresh date","Supplier payment terms"],a:1,why:"Item master inconsistency and differing purchase conditions explain most apparent price variance, and presenting before checking costs credibility."} },

    { id:"l5", title:"Choosing metrics that drive the right behaviour", mins:7,
      body:"<p>Every metric creates an incentive, and metrics chosen without thinking about the incentive produce behaviour nobody intended.</p><p>Inventory turns alone drive stock cuts that cause stockouts. On-time delivery alone drives padded lead times. Savings alone drive decisions that increase risk in categories where continuity matters more than cost. Each metric is reasonable; each becomes distorting when it stands unpaired.</p><p>The remedy is paired metrics that constrain each other: turns alongside service level, savings alongside supplier risk, cost per unit alongside quality and total cost. The pairing makes the trade-off visible rather than letting one side of it disappear.</p><p>Keep the reported set small. A dashboard with forty metrics is not measured, it is displayed, and nobody can tell which movement matters. Five to eight paired measures that leadership actually reviews will change more than a comprehensive scorecard that is never opened.</p>",
      keyPoints:["Unpaired metrics produce predictable distortions","Pair metrics so the trade-off stays visible","A small reviewed set beats a comprehensive unread one"],
      check:{q:"A team is measured only on savings. The predictable distortion is:",opts:["Excessive tendering activity","Decisions that book savings while transferring risk, such as sole-sourcing to a cheaper supplier with weaker continuity","Reduced supplier count","Slower processing"],a:1,why:"A metric that counts only price captures none of the risk created to achieve it, and behaviour follows the metric."} }
  ]}]
}
];

const COURSES_C = [
{
  id:"c-esg-1", dom:"esg", title:"Sustainable & Ethical Procurement in Canada",
  level:[1,4], cpd:8,
  blurb:"Scope 3, Bill S-211 forced labour reporting, supplier codes, and Indigenous and social procurement in the Canadian context.",
  modules:[
  { title:"Environmental",
    lessons:[
    { id:"l1", title:"Why Scope 3 lands on procurement", mins:7,
      body:"<p>Emissions are reported in three scopes. Scope 1 is direct emissions from sources the organization owns. Scope 2 is indirect emissions from purchased energy. Scope 3 is everything else across the value chain, including purchased goods and services, transportation, business travel, and end-of-life treatment.</p><p>For most organizations that are not heavy industrial emitters, Scope 3 accounts for the large majority of the total footprint, and the largest single component is usually purchased goods and services. That is procurement's spend. An emissions target therefore becomes a sourcing problem almost immediately, whether or not procurement was in the room when it was set.</p><p>The practical implication is that supplier selection, specification and category strategy become emissions levers. It also means procurement needs a seat in target-setting, because targets set without reference to what the supply base can actually deliver produce commitments that cannot be met.</p>",
      keyPoints:["Scope 3 usually dominates the total footprint","Purchased goods and services is typically the largest component","Emissions targets become sourcing decisions"],
      check:{q:"A services organization commits to net zero. The largest emissions reduction opportunity most likely sits in:",opts:["Office energy use","Purchased goods and services within Scope 3, since that is where the majority of the footprint sits for most service organizations","Employee commuting","Company vehicles"],a:1,why:"Scope 1 and 2 are visible and controllable but usually small relative to the supply chain footprint."} },

    { id:"l2", title:"Measuring supply chain emissions without perfect data", mins:8,
      body:"<p>Two approaches exist and the choice is usually sequential rather than either-or.</p><p><strong>Spend-based estimation</strong> applies emission factors to spend by category. It is quick, covers everything, and is imprecise. Its weakness is that it cannot distinguish a low-carbon supplier from a high-carbon one in the same category, so it will not show improvement when you switch.</p><p><strong>Supplier-specific data</strong> uses actual reported figures. It is accurate and responsive to your decisions, but it is slow to gather and many suppliers cannot provide it.</p><p>The workable sequence is to baseline everything with spend-based estimation, use that to identify the categories carrying the footprint, then pursue supplier-specific data only in those categories. That concentrates effort where it changes the number.</p><p>Do not wait for good data before acting. The categories that dominate a spend-based baseline are usually obvious enough to start work on, and precision can improve alongside the reduction effort rather than before it.</p>",
      keyPoints:["Spend-based estimation baselines everything but cannot show improvement","Pursue supplier-specific data only in material categories","Do not wait for precision before acting"],
      check:{q:"The limitation of spend-based emissions estimation is:",opts:["It is too expensive","It cannot distinguish between suppliers within the same category, so switching to a lower-carbon supplier does not change the reported figure","It excludes transportation","It requires supplier cooperation"],a:1,why:"Spend-based factors are category averages, which makes the method useful for baselining and useless for demonstrating supplier-level improvement."} }
  ]},
  { title:"Social and Ethical",
    lessons:[
    { id:"l3", title:"Bill S-211 and forced labour reporting", mins:8,
      body:"<p>Canada's <em>Fighting Against Forced Labour and Child Labour in Supply Chains Act</em> requires covered entities to report annually on the steps taken to prevent and reduce the risk of forced and child labour in their supply chains.</p><p>Two points are commonly misunderstood. First, the obligation is <strong>to report on process</strong>, not to certify that supply chains are clean. A report saying the organization has assessed risk in certain categories and has work outstanding is compliant; one that overstates assurance is a governance problem.</p><p>Second, the report must be <strong>approved by the governing body</strong> and published. That elevates it well beyond a procurement document. Whoever signs it is attesting to statements that procurement usually supplies, which means the evidence behind them has to be real.</p><p>Practically, the report covers structure and supply chains, policies and due diligence, risk identification, remediation, training and effectiveness assessment. Building a defensible risk assessment by category and geography is the work that makes the rest possible, and it takes longer than the reporting deadline suggests.</p>",
      keyPoints:["The obligation is to report on process, not certify cleanliness","Governing body approval makes accuracy a governance matter","Risk assessment by category and geography is the foundational work"],
      check:{q:"A covered entity's report states its supply chain is confirmed free of forced labour based on supplier attestations. The concern is:",opts:["Attestations are not required","The statement claims assurance that attestations alone cannot support, creating exposure for the governing body that approved it","Reports need not be published","The wording is standard"],a:1,why:"Unverified attestations do not establish the conclusion claimed, and the report carries board-level approval."} },

    { id:"l4", title:"Supplier codes of conduct with teeth", mins:7,
      body:"<p>Nearly every organization has a supplier code of conduct. Most are signed at onboarding, filed, and never referenced again, which transfers paperwork rather than risk and provides little defence when a problem surfaces.</p><p>Four elements make a code operational. <strong>Risk-based verification</strong>, so that assurance effort concentrates where exposure actually sits rather than being spread evenly across the supply base. <strong>Contractual incorporation</strong>, so the code is an obligation rather than an aspiration. <strong>Defined consequences</strong>, with a graduated response from corrective action plan through to termination. And <strong>a remediation pathway</strong>, because immediate termination on discovering a problem often harms the workers involved rather than helping them.</p><p>That fourth point is the one organizations handle worst. Responsible practice usually favours engagement and improvement over exit, with exit reserved for suppliers unwilling to remediate. Cutting and running protects your reputation while leaving the underlying harm in place.</p>",
      keyPoints:["Unverified attestation transfers paperwork, not risk","Incorporate the code contractually","Remediation usually serves workers better than immediate termination"],
      check:{q:"An audit finds a labour violation at a supplier. The most responsible first response is generally:",opts:["Immediate termination","A time-bound corrective action plan with verification, reserving termination for unwillingness to remediate","Public disclosure","Reducing order volume"],a:1,why:"Exit removes your exposure but typically worsens outcomes for affected workers. Engagement with verification addresses the harm."} },

    { id:"l5", title:"Indigenous and social procurement", mins:7,
      body:"<p>Social procurement uses purchasing to generate community benefit alongside the goods or services acquired. In Canada, Indigenous procurement is the most developed strand, driven by federal targets, provincial commitments and corporate reconciliation action plans.</p><p>Doing it well requires separating three things that are frequently conflated. <strong>Supplier identification</strong>, using recognized directories and certification bodies rather than self-declaration alone. <strong>Genuine capability development</strong>, which may mean unbundling large contracts into scopes that emerging businesses can realistically bid, adjusting insurance and bonding requirements that exclude smaller firms without reducing genuine risk protection, and improving payment terms. <strong>Measurement</strong>, tracking actual spend and outcomes rather than the number of suppliers invited to bid.</p><p>The failure mode to avoid is tokenism, where a joint venture exists on paper to satisfy a requirement while the work flows elsewhere. Credible programs verify substantive participation, and the organizations running them are generally candid that this takes longer than the target implies.</p>",
      keyPoints:["Use recognized certification rather than self-declaration","Unbundling and payment terms often matter more than outreach","Measure actual spend and outcomes, not bids invited"],
      check:{q:"The most effective structural change to increase Indigenous supplier participation is often:",opts:["Adding an evaluation preference","Unbundling large contracts into scopes emerging businesses can realistically deliver, and reviewing bonding and payment terms that exclude smaller firms","Publishing a commitment statement","Hosting supplier events"],a:1,why:"Evaluation preferences do not help suppliers who cannot meet the scale, bonding or cash flow requirements to bid at all."} }
  ]}]
},

{
  id:"c-dig-1", dom:"dig", title:"Digital Supply Chain & Applied AI",
  level:[1,4], cpd:8,
  blurb:"ERP and master data, source-to-pay platforms, automation, and where AI genuinely helps a supply chain function.",
  modules:[
  { title:"Systems and Data",
    lessons:[
    { id:"l1", title:"Master data is the foundation", mins:7,
      body:"<p>Every analysis, report and automated process reads master data: item records, supplier records, locations, units of measure, pricing conditions. When that layer is inconsistent, everything built on it inherits the problem, and the symptoms appear far from the cause.</p><p>Four failures account for most of the damage. <strong>Duplicate suppliers</strong>, which fragment spend analysis and conceal negotiating leverage. <strong>Duplicate or inconsistent item records</strong>, which create false price variance and prevent demand from being aggregated. <strong>Unit of measure errors</strong>, which produce order quantity mistakes that are expensive and embarrassing. <strong>Stale records</strong>, where lead times and pricing were entered at implementation and never revisited, quietly driving wrong planning decisions for years.</p><p>Governance rather than cleanup is the durable answer. A one-time cleansing project degrades within a year unless there is a defined owner, a creation process with validation, and periodic review. The cleanup is worth doing, but only alongside the process that stops the re-accumulation.</p>",
      keyPoints:["Everything downstream inherits master data problems","Stale lead times silently drive wrong planning for years","Cleanup without governance degrades within a year"],
      check:{q:"After a data cleansing project, duplicate suppliers reappear within a year. The missing element was:",opts:["Better cleansing tools","Governance: a defined owner, validated creation process and periodic review to prevent re-accumulation","Staff training","A new ERP"],a:1,why:"Cleansing addresses the stock of bad data. Only governance addresses the flow that creates it."} },

    { id:"l2", title:"ERP, WMS, TMS and source-to-pay: what does what", mins:7,
      body:"<p>The system landscape confuses people because functions overlap and vendors claim broad coverage.</p><p><strong>ERP</strong> is the transactional and financial backbone: purchase orders, receipts, invoices, inventory records, the general ledger. It is the system of record and generally weak at specialized operational execution.</p><p><strong>WMS</strong> manages warehouse execution: directed putaway, pick paths, slotting, cycle counting. It exists because ERP inventory modules track what you have rather than orchestrating how it moves.</p><p><strong>TMS</strong> manages transportation: rate shopping, load building, routing, freight audit.</p><p><strong>Source-to-pay</strong> covers the commercial process ahead of the transaction: sourcing events, contract repository, supplier management, requisitioning and invoice matching.</p><p>The decision that matters is where each master record lives and which system is authoritative when they disagree. Implementations fail on integration and data ownership far more often than on functionality, and that question should be settled before selection rather than during deployment.</p>",
      keyPoints:["ERP is the system of record; specialist systems handle execution","Decide which system is authoritative for each record","Integration and data ownership cause more failures than functionality"],
      check:{q:"WMS and ERP disagree on inventory quantity. The governing question is:",opts:["Which was updated most recently","Which system was designated authoritative for inventory at design time, and whether the integration is functioning as specified","Which shows the higher quantity","Whether a count is needed"],a:1,why:"Without a designated authoritative source, every discrepancy becomes an investigation with no defined resolution."} },

    { id:"l3", title:"Automation: choosing what to automate", mins:7,
      body:"<p>Automation returns value when a process is high-volume, rule-based, and stable. It destroys value when applied to a process that is none of those, or to a broken process, because automating a broken process produces errors faster.</p><p>Assess candidates on four questions. <strong>Volume</strong>: how often does this run? <strong>Rule clarity</strong>: can the decision be expressed in rules a person would agree with? <strong>Stability</strong>: how often do the rules change? <strong>Exception rate</strong>: what share of cases needs human judgement anyway?</p><p>That last one is decisive. A process automated at 60% with a 40% exception rate often costs more than the manual version, because you now maintain an automation and handle exceptions through a pathway nobody designed properly.</p><p>Fix the process first. The most common outcome of a serious automation assessment is the discovery that three approval steps can be removed entirely, which delivers most of the benefit without building anything.</p>",
      keyPoints:["High volume, clear rules, stable, low exception rate","A high exception rate can make automation cost more","Simplifying the process often beats automating it"],
      check:{q:"An invoice matching process has a 35% exception rate. Before automating you should:",opts:["Automate the 65% that matches cleanly","Investigate why a third of invoices fail to match, since the causes are usually fixable upstream and fixing them delivers more than automation would","Increase tolerance thresholds","Outsource the process"],a:1,why:"A high exception rate reflects upstream data and process problems. Automating around it preserves the cause and adds maintenance."} }
  ]},
  { title:"Applied AI",
    lessons:[
    { id:"l4", title:"Where AI genuinely helps a supply chain function", mins:8,
      body:"<p>Value concentrates where work is high-volume, pattern-based, and verifiable by a person who knows the domain.</p><p>Strong current applications include <strong>spend classification</strong>, categorizing transactions far faster than manual mapping; <strong>contract data extraction</strong>, pulling terms, dates and obligations from a document portfolio to populate a register; <strong>document drafting</strong>, producing first drafts of specifications, evaluation criteria or supplier communications for review; <strong>demand sensing</strong>, incorporating signals a statistical model misses; and <strong>anomaly detection</strong> in spend and invoices.</p><p>The pattern across all of these is that a human remains accountable for the output. That is not a temporary limitation. In procurement, and especially in public sector and association contexts, decisions about who wins work must be explainable and defensible, and an output nobody can explain is not usable regardless of quality.</p><p>Be specific about verification. Extraction that is 95% accurate across 400 contracts means roughly 20 wrong records, and which 20 matters.</p>",
      keyPoints:["Best fit: high volume, pattern-based, human-verifiable","Keep a person accountable for decisions that must be defensible","Specify how output will be verified before deploying"],
      check:{q:"AI extracts contract terms at 95% accuracy across 400 contracts. The correct interpretation is:",opts:["The output is reliable enough for direct use","Roughly 20 records are wrong, so a verification step is required, prioritized by contract value and risk","Accuracy must reach 100% before use","The tool is unsuitable"],a:1,why:"High aggregate accuracy still leaves errors that matter. The practical answer is risk-weighted verification rather than abandoning the tool."} },

    { id:"l5", title:"Governing AI use in procurement", mins:7,
      body:"<p>Using AI in procurement raises questions that do not arise in other functions, because procurement decisions affect who receives public or organizational money.</p><p>Four principles apply. <strong>Explainability</strong>: if an output influences an award, you must be able to explain the basis. A model that cannot be explained cannot support a defensible decision. <strong>Human accountability</strong>: a named person owns the decision, which means substantive review rather than rubber-stamping. <strong>Data protection</strong>: supplier pricing and proposal content are confidential, and feeding them into systems without knowing where the data goes can breach the confidentiality undertaking in your own RFP. <strong>Bias awareness</strong>: a model trained on historical awards will reproduce historical patterns, which is a direct problem where the organization has diversity or Indigenous procurement commitments.</p><p>Write this into policy before the tools are in use rather than after. Retrofitting governance onto established practice is considerably harder, and in a public or association setting the first challenge tends to arrive before the policy does.</p>",
      keyPoints:["Outputs influencing awards must be explainable","Confidential supplier data needs a known data path","Models trained on history reproduce historical bias"],
      check:{q:"A tool scores supplier proposals using patterns from past awards. The primary governance concern is:",opts:["Processing speed","It reproduces historical award patterns, which conflicts with diversity commitments and cannot be explained to a challenging proponent","Licensing cost","Integration effort"],a:1,why:"Both explainability and bias fail here, and either alone is enough to make an award indefensible."} }
  ]}]
},

{
  id:"c-lead-1", dom:"lead", title:"Leading the Supply Chain Function",
  level:[1,4], cpd:9,
  blurb:"Influencing without authority, change management, executive communication and building a team that gets listened to.",
  modules:[
  { title:"Influence",
    lessons:[
    { id:"l1", title:"Influencing without authority", mins:7,
      body:"<p>Supply chain professionals rarely control the people whose behaviour they need to change. Requisitioners, engineers, operations managers and finance all make decisions that determine whether a category strategy works, and none of them report to procurement.</p><p>The mechanism that works is translation. Every stakeholder is measured on something, and your proposal either helps with that or it does not. A consolidation that reduces supplier count is a procurement benefit; expressed to an operations manager, the relevant fact is whether it reduces the number of vendors they chase when something fails. Same change, different frame, entirely different reception.</p><p>Two practices follow. Find out what each stakeholder is accountable for before proposing anything, which usually takes one conversation. And bring them in early enough that their input can still change the design, because participation produces advocacy while consultation on a finished plan produces resentment.</p><p>Policy compliance is the weakest available tool and should be the last one reached for.</p>",
      keyPoints:["Translate proposals into each stakeholder's own objectives","Involve people early enough that input can still change things","Policy compliance is the weakest lever"],
      check:{q:"Engineering resists a consolidation that removes their preferred supplier. The most useful first step is:",opts:["Present the savings analysis again","Understand what the preferred supplier provides that matters to them technically, and whether the alternative genuinely covers it","Escalate to the engineering director","Proceed under procurement policy"],a:1,why:"Resistance from technical stakeholders frequently reflects a real requirement the commercial analysis did not capture."} },

    { id:"l2", title:"Communicating with executives", mins:7,
      body:"<p>Executives allocate attention across many areas and will give yours a few minutes. What they need first is the implication and the decision required, not the method that produced it.</p><p>Structure accordingly. Open with the conclusion or the ask. Follow with the two or three facts that support it. Hold the detail in reserve for questions, which is where your analytical work actually earns its place.</p><p>Quantify in terms the organization already uses. Procurement metrics such as savings rate or supplier count mean less to an executive than cash released, risk exposure reduced, or a service commitment protected.</p><p>Be clear about what you want. A great many supply chain presentations end without an ask, and the meeting produces interest, agreement in principle and no decision. Say explicitly what you need: a decision, a budget, a mandate, or sponsorship for a change that will meet resistance.</p><p>Bring bad news early and with options. Executives forgive problems; they do not forgive being surprised by problems that were known.</p>",
      keyPoints:["Lead with the implication and the ask","Quantify in the organization's terms, not procurement's","Bring bad news early, with options"],
      check:{q:"Your supply risk briefing generates interest but no decision. The most likely cause is:",opts:["Insufficient data","No explicit ask, so there was nothing specific to decide on","Wrong audience","Presentation too short"],a:1,why:"Briefings without a defined decision request reliably produce agreement in principle and no action."} }
  ]},
  { title:"Change and Team",
    lessons:[
    { id:"l3", title:"Leading change people did not ask for", mins:8,
      body:"<p>Most supply chain change removes discretion from someone. Centralizing purchasing, standardizing specifications, mandating a system: each takes away a choice a person previously had, and each will be experienced that way regardless of the benefit at organizational level.</p><p>Three things determine whether it holds. <strong>Participation in design</strong>, so legitimate local requirements are built in rather than discovered during rollout as resistance. <strong>A credible explanation</strong> of why the change is happening, which means the actual reason rather than a framing. People generally accept a reason they dislike and rarely accept one they suspect is not true. <strong>Visible responsiveness</strong>, where the first few objections raised are seen to be addressed, which is what signals whether input is genuinely wanted.</p><p>Expect the middle of the change to be worse than the start. The old way has stopped and the new way is not yet fluent. Leaders who have not prepared for that trough often reverse course at exactly the point where persistence was required.</p>",
      keyPoints:["Most change removes someone's discretion","Give the real reason, not a framing","Expect a performance trough in the middle"],
      check:{q:"Six weeks into a centralization, complaints rise and compliance drops. The most likely reading is:",opts:["The change has failed and should be reversed","This is the expected trough between old fluency and new, and the response is targeted support rather than reversal","Enforcement should be increased","Local autonomy should be restored"],a:1,why:"The dip is predictable. Reversing at this point is how organizations conclude that change does not work while never completing one."} },

    { id:"l4", title:"Building a team that gets listened to", mins:7,
      body:"<p>Functions earn influence through the quality and reliability of what they produce, not through reporting line or mandate. Three capabilities determine whether a supply chain team is consulted early or informed late.</p><p><strong>Analytical credibility.</strong> Numbers that hold up under scrutiny. One overstated saving discovered by finance costs more credibility than ten sound analyses build.</p><p><strong>Commercial judgement.</strong> Knowing when the lowest price is wrong, when a risk is worth taking, when to escalate. This develops through exposure to consequential decisions, which means delegating real ones rather than protecting people from them.</p><p><strong>Business literacy.</strong> Understanding what the organization does and what constrains it. A team that can discuss operational realities gets invited into decisions early, which is where supply chain adds the most value.</p><p>Develop these deliberately. Give people categories to own end to end, expose them to the operations they buy for, and have them present their own work rather than presenting it for them.</p>",
      keyPoints:["Influence is earned through reliable output","Commercial judgement develops through real decisions","Have people present their own work"],
      check:{q:"The fastest way to lose functional credibility is:",opts:["Missing a deadline","An overstated savings figure that finance disproves, since it casts doubt on every other number the function produces","Disagreeing with an executive","Losing a supplier negotiation"],a:1,why:"Analytical trust is the foundation everything else rests on, and it is asymmetric: slow to build and quick to lose."} },

    { id:"l5", title:"Making the case for the function", mins:7,
      body:"<p>Supply chain teams are frequently under-resourced because the value they create is hard to see. Avoided disruptions do not appear in any report, and a well-run category generates no events at all.</p><p>Build the case on three foundations. <strong>A value narrative beyond savings</strong>: cash released, risk reduced, compliance obligations met, emissions addressed, capability built. Savings-only reporting eventually pushes the function toward decisions that look good and are wrong.</p><p><strong>Evidence of what would happen without the work.</strong> The supplier failure that was caught during qualification. The contract that would have auto-renewed at an above-market rate. These are the strongest arguments available and almost nobody records them, because at the time they feel like routine work rather than saved losses.</p><p><strong>A clear statement of what more capacity would deliver.</strong> Not more people to do more of the same, but specific categories currently unmanaged and the value sitting in them.</p><p>Keep a running record of prevented problems. Twelve months of them is a far more persuasive document than any benchmarking study.</p>",
      keyPoints:["Report value beyond savings or the scorecard drives bad decisions","Record prevented problems as they happen","Tie resource requests to specific unmanaged value"],
      check:{q:"The most persuasive evidence for additional procurement resource is usually:",opts:["Industry benchmarks on procurement staffing ratios","A documented record of problems prevented, plus named categories currently unmanaged and the value in them","Comparison with competitor team sizes","Current workload statistics"],a:1,why:"Specific, organization-grounded evidence outperforms external benchmarks, which executives discount as not reflecting their situation."} }
  ]}]
}
];

/* Assemble the full catalogue */
const COURSES = [].concat(COURSES_A, COURSES_B, COURSES_C);
const COURSE_BY_ID = {};
let TOTAL_LESSONS = 0;
COURSES.forEach(function (c) {
  COURSE_BY_ID[c.id] = c;
  c.lessonCount = 0;
  c.modules.forEach(function (m, mi) {
    m.index = mi;
    m.lessons.forEach(function (l, li) {
      l.index = li;
      l.moduleIndex = mi;
      l.courseId = c.id;
      l.uid = c.id + "::" + mi + "::" + li;
      c.lessonCount++;
      TOTAL_LESSONS++;
    });
  });
});
